-- ============================================================
-- 表：hp_cache_res_hot_list
-- 来源：.cache/api_responses/
-- 由 sql/cache_data.sql 统一加载；也可单独执行本文件
-- 时间粒度：month → period_key YYYY-MM（body 内 entries 按小时分槽）
-- asset_key 保留平台前缀（tencenthot_ / weibohot_ / bilibilihot_ / douyinhot_ / iqiyihot_），五个平台共用一张表
-- ============================================================
SET NAMES utf8mb4;

-- ── hp_cache_res_hot_list  [热搜榜单]  1 个文件 ────────────
DROP TABLE IF EXISTS `hp_cache_res_hot_list`;
CREATE TABLE `hp_cache_res_hot_list` (
  `asset_key` VARCHAR(191) NOT NULL COMMENT '缓存文件名（含平台前缀，如 tencenthot_2026-11；五个平台共用）',
  `body` LONGTEXT NOT NULL COMMENT '原始响应 JSON 全文',
  `cache_updated_at` BIGINT NOT NULL DEFAULT 1795791234763,
  `period_type` VARCHAR(8) NOT NULL DEFAULT 'static' COMMENT '时间粒度：day/month/year/static',
  `period_key` VARCHAR(10) NOT NULL DEFAULT '' COMMENT '粒度日期：YYYY-MM-DD / YYYY-MM / YYYY，静态为空',
  PRIMARY KEY (`asset_key`),
  KEY `idx_cache_period` (`period_type`, `period_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='热搜榜单响应（五个平台共用，asset_key 按平台区分，基于 api_responses 分类）';

